'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const root=path.resolve(__dirname,'..');
const F=require(path.join(root,'JS/tarot-foundation.js'));
const E=require(path.join(root,'JS/tarot-semantic-engine.js'));
const source=fs.readFileSync(path.join(root,'JS/tarot_upgrade.js'),'utf8');
const uiSource=fs.readFileSync(path.join(root,'JS/ui.js'),'utf8');
function productionSlice(start,end){const a=source.indexOf(start);assert(a>=0,'Production function is present');const b=source.indexOf(end,a+start.length);assert(b>a,'Production function closes');return source.slice(a,b+end.length);}

const window={_jyMathersSignificatorId:13,JYTarotReading:{orientation(){return true;},apply(card){card.sourceProfile='rws_reversals';}}};
const sandbox={window,console,Math,Date,Set,makeSeededRng(seed){let state=0;for(const c of seed)state=(Math.imul(state,31)+c.charCodeAt(0))>>>0;return ()=>((state=(Math.imul(state,1664525)+1013904223)>>>0)/4294967296);}};
vm.createContext(sandbox);
vm.runInContext(productionSlice('(function(){\n  if (window.JY_buildCanonicalTarotDraw) return;','\n})();'),sandbox,{filename:'tarot_upgrade canonical production'});
const deck=Array.from({length:78},(_,id)=>({id,n:'牌'+id,rank:id%13===0?'king':id%13===1?'queen':'pip',suit:'wand'}));
const q='請用 Mathers 第三法看未來工作';
const route=F.routeQuestion(q);
assert.equal(route.spreadId,'mathers_66');
assert.equal(route.methodPlan.count,68);
assert.equal(route.methodPlan.slots[66].label.startsWith('左側意外牌'),true);
assert.equal(route.methodPlan.slots[67].label.startsWith('右側意外牌'),true);
assert.equal(route.methodPlan.slots[0].slotKind,'sequence_member');
assert.equal(route.methodPlan.slots[66].slotKind,'surprise_conclusion');
assert.equal(route.methodPlan.slots[67].slotKind,'surprise_conclusion');
assert.deepEqual(F.validateMethodRegistry(),{ok:true,errors:[]});
for(const phrasing of ['請用Mathers第三法看感情','請用Mathers 66 張占工作','請用六十六張牌陣看事業'])assert.equal(F.routeQuestion(phrasing).spreadId,'mathers_66');
assert.notEqual(F.routeQuestion('不要使用 Mathers 第三法，幫我看工作').spreadId,'mathers_66');
const definition={id:'mathers_66',count:68,positions:route.methodPlan.slots.map((slot,i)=>({name:'位置'+(i+1),zh:slot.label}))};
const cards=window.JY_buildCanonicalTarotDraw(deck,'mathers_66',definition,'verify-66-plus-two','career',q);
assert.equal(cards.length,68);
assert.equal(new Set(cards.map(card=>card.id)).size,68);
assert(!cards.some(card=>card.id===13),'The significator cannot also appear in 66 cards or 2 surprises');
const expectedMain=deck.filter(card=>card.id!==13).slice(0,66);
assert.deepEqual(Array.from(cards.slice(0,66),card=>card.id),expectedMain.map(card=>card.id),'All 66 main cards follow the deck order after withdrawing significator');
const unusedBefore=deck.filter(card=>card.id!==13).slice(66).map(card=>card.id);
assert.equal(unusedBefore.length,11);
assert(unusedBefore.includes(cards[66].id));
assert(unusedBefore.includes(cards[67].id));
assert.notEqual(cards[66].id,cards[67].id);
const meta=cards[0].drawProcedure;
assert.deepEqual([meta.initialDealtCount,meta.initialUnusedCount,meta.remainingUnusedCount,meta.largeCircleImplemented],[66,11,9,false]);
assert.equal(meta.significator.id,13);
assert.equal(meta.surprises.left.id,cards[66].id);
assert.equal(meta.surprises.right.id,cards[67].id);
assert.equal(cards.filter(card=>card.mathersPeriod==='past').length,22);
assert.equal(cards.filter(card=>card.mathersPeriod==='present').length,22);
assert.equal(cards.filter(card=>card.mathersPeriod==='future').length,22);
assert.equal(cards.filter(card=>card.mathersPeriod==='conclusion').length,2);
assert.equal(cards.length+meta.remainingUnusedCount+1,78,'68 displayed + 9 still unused + one significator = 78');
assert.throws(()=>window.JY_buildCanonicalTarotDraw(deck.slice(0,77),'mathers_66',definition,'bad','career',q),/78張/);
assert.throws(()=>window.JY_buildCanonicalTarotDraw(deck.slice(0,77).concat(deck[0]),'mathers_66',definition,'bad','career',q),/78張/);

// Execute the production layout with minimal card-slot renderer: assert genuine UI contains every unique slot.
sandbox.S=(_,slot)=>'<span id="t-slot-'+slot+'"></span>';
sandbox.drawnCards=cards;
sandbox._jyCurSpreadId='';
sandbox.getTarotCardImage=card=>'assets/'+card.id+'.png';
vm.runInContext(productionSlice('  function buildSlotLayout(spreadId, def) {','  window.buildSlotLayout = buildSlotLayout;'),sandbox,{filename:'tarot_upgrade original layout production'});
const html=window.buildSlotLayout('mathers_66',definition);
const slots=Array.from(html.matchAll(/id="t-slot-(\d+)"/g),m=>Number(m[1]));
assert.equal(slots.length,68,'66 original numbered positions and two surprise positions exist');
assert.equal(new Set(slots).size,68,'No slot is shown twice or lost');
assert.deepEqual(slots.slice().sort((a,b)=>a-b),Array.from({length:68},(_,i)=>i+1));
assert.match(html,/aria-label="Mathers 第三法可左右捲動/);
assert.match(html,/琥珀＝過去/);
assert.match(html,/從右往左讀/);
assert.match(html,/原書最後重排大圓有文字歧義/);
assert.match(html,/assets\/13.png/);
assert(uiSource.includes("def.id === 'mathers_66'")&&uiSource.includes("'mathers_66','fifteen_card'"),'Both user-triggered and resumed UI paths call canonical constructor');
assert(source.includes("/^(?:mathers_21|mathers_66|mathers_horseshoe)$/.test(def.id)"),'Tapping deck does not consume Mathers cards one by one');
// The actual RWS export must keep the significator and both surprises in local prompt data.
const readingWindow={document:{addEventListener(){}},S:{form:{type:'career',question:q}}};
const readingScope={window:readingWindow,console,Math,Date,Set,getTarotCardImage:card=>'assets/'+card.id+'.png'};
vm.createContext(readingScope);
vm.runInContext(fs.readFileSync(path.join(root,'JS/tarot-reading.js'),'utf8'),readingScope,{filename:'tarot-reading production'});
const reading=readingWindow.JYTarotReading;
const readingCards=Array.from(cards,card=>Object.assign({},card,{readingMode:'rws_reversals',sourceProfile:'rws_reversals'}));
const exported=reading.payload({compiledQuestion:{features:{referenceDate:'2026-09-23'}}},q,readingCards,'mathers_66',route.methodPlan,definition);
assert.equal(exported.tarotData.cards.length,68);
assert.equal(exported.tarotData.drawProcedure.significator.id,13);
assert.equal(exported.tarotData.drawProcedure.surprises.right.id,readingCards[67].id);
assert.equal(exported.tarotData.cards[66].slotKind,'surprise_conclusion');
assert.match(reading.formatData(exported.tarotData),/初次留11張、另抽2張後仍未使用9張/);
const badSurprise=readingCards.map(card=>Object.assign({},card));
badSurprise[67]=Object.assign({},badSurprise[67],{id:13});
assert.throws(()=>reading.payload({},q,badSurprise,'mathers_66',route.methodPlan,definition),/代表牌|紀錄/);
const noProvenance=readingCards.map(card=>Object.assign({},card));
delete noProvenance[0].drawProcedure;
assert.throws(()=>reading.payload({},q,noProvenance,'mathers_66',route.methodPlan,definition),/紀錄/);
const gdCards=readingCards.map((card,i)=>({name:card.n,position:route.methodPlan.slots[i].label,sourceCore:'實際牌義從Book T提供',element:['火','風','水','土'][i%4]}));
const contract=E.compileReadingSpec({question:q,spreadId:'mathers_66',methodPlan:route.methodPlan,cards:gdCards,sourceProfile:'gd_book_t',referenceDate:'2026-09-23'});
assert.equal(contract.validation.ok,true,contract.validation.errors.join(','));
assert.equal(contract.method.id,'mathers_66');
assert.equal(contract.evidenceGraph.evidenceUnits.filter(unit=>unit.type==='ordered_period_row').length,6);
assert.equal(contract.evidenceGraph.evidenceUnits.filter(unit=>unit.type==='declared_temporal_pair').length,66);
assert.equal(contract.evidenceGraph.evidenceUnits.filter(unit=>unit.type==='declared_outer_pair').length,33);
assert.equal(contract.evidenceGraph.evidenceUnits.filter(unit=>unit.type==='surprise_conclusion_member_node').length,2);
assert.equal(contract.evidenceGraph.evidenceUnits.find(unit=>unit.type==='arch_surprise_synthesis').metadata.largeCircleImplemented,false);
const missing=E.compileReadingSpec({question:q,spreadId:'mathers_66',methodPlan:route.methodPlan,cards:gdCards.slice(0,67),sourceProfile:'gd_book_t',referenceDate:'2026-09-23'});
assert.equal(missing.validation.ok,false);
assert(missing.validation.errors.some(error=>error.startsWith('card_count_mismatch:67/68')));
console.log('card-audit-mathers-third: 78-card conservation, period ranges, 68 real UI slots, source ambiguity, routing and failures passed.');
